with source as (select value as j from jsonb_array_elements('[{"id":"3286e381-2c2d-459f-be4c-5150a2576c0b","name":"Mira Törnstig","race":"Människa","tags":["huvudfigur","färdigheter","återkommande","vägvisare","allierad"],"armor":{"name":"Härdat läder","absorption":4,"armor_type_id":"5d5f3274-101d-412b-b27a-72c0dff469b6"},"hooks":["Anställs av samma uppdragsgivare som rollpersonerna och gör först ett uselt intryck.","Visar ett vägskäl som inte finns på någon karta och ber gruppen välja riktning.","Ber gruppen hjälpa henne hämta kompassen från en tjuv som känner dess hemlighet."],"title":"Vägvisare, klättrare och äventyrare","active":true,"gender":"Kvinna","shield":{"bv":null,"fv":null,"name":""},"skills":[{"fv":17,"erf":0,"name":"Klättra","skill_id":"klattra"},{"fv":15,"erf":0,"name":"Akrobatik","skill_id":"akrobatik"},{"fv":16,"erf":0,"name":"Spåra","skill_id":"spara"},{"fv":17,"erf":0,"name":"Överlevnad","skill_id":"overlevnad"},{"fv":17,"erf":0,"name":"Orientering","skill_id":"orientering"},{"fv":15,"erf":0,"name":"Navigera","skill_id":"navigera"},{"fv":16,"erf":0,"name":"Finna dolda ting","skill_id":"finna_dolda_ting"},{"fv":15,"erf":0,"name":"Hantera fällor","skill_id":"hantera_fallor"},{"fv":16,"erf":0,"name":"Lyssna","skill_id":"lyssna"},{"fv":17,"erf":0,"name":"Upptäcka fara","skill_id":"upptacka_fara"},{"fv":15,"erf":0,"name":"Smyga","skill_id":"smyga"},{"fv":14,"erf":0,"name":"Första hjälpen","skill_id":"forsta_hjalpen"},{"fv":14,"erf":0,"name":"Geografi","skill_id":"geografi"},{"fv":13,"erf":0,"name":"Rida","skill_id":"rida"},{"fv":15,"erf":0,"name":"Dolkar","skill_id":"dolkar"},{"fv":14,"erf":0,"name":"Enhandssvärd","skill_id":"enhandssvard"},{"fv":12,"erf":0,"name":"Taktik","skill_id":"taktik"},{"fv":13,"erf":0,"name":"Bluffa","skill_id":"bluffa"},{"fv":15,"erf":0,"name":"Gömma sig","skill_id":"gomma_sig"},{"fv":15,"erf":0,"name":"Ilmarsch","skill_id":"ilmarsch"},{"fv":11,"erf":0,"name":"Klubbor & hammare","skill_id":"klubbor_hammare"}],"spells":[],"npc_key":"mira-tornstig","secrets":"Bär en liten kompass som ibland pekar mot den person hon saknar istället för norr. Hon har hållit det hemligt för att ingen ska ta föremålet.","weapons":[{"bv":15,"fv":14,"bep":1,"name":"Kortsvärd","tags":["sword","edged"],"range":"","damage":"1T6+1","length":1,"handling":"1H","weapon_id":"392eecf3-0bec-4f5a-8467-e67e322a96bd","weaponType":"L","weaponTypeId":"392eecf3-0bec-4f5a-8467-e67e322a96bd","strengthGroup":1,"weaponCategory":"melee"},{"bv":9,"fv":15,"bep":0.5,"name":"Dolk","tags":["dagger","edged"],"range":"","damage":"1T4+1","length":0,"handling":"1H","weapon_id":"112c2fed-42ae-41d9-8ca1-f099d2707bbd","weaponType":"L","weaponTypeId":"112c2fed-42ae-41d9-8ca1-f099d2707bbd","strengthGroup":1,"weaponCategory":"melee"}],"gm_notes":"Återkommande neutral/allierad SLP. Kan sälja vägledning, leda genom omöjlig terräng eller själv behöva räddas. Ta aldrig kontrollen över gruppens utforskande; ge henne brister och låt RP fatta vägvalen. Porträtt: WIDE_MASTER_PORTRAIT_WOMAN_20261018.png, identitetsmaster i HERMES.","weakness":"Tar orimliga risker för främlingar och kan inte lämna ett låst skrin eller ett olöst vägskäl i fred.","age_years":33,"appearance":"Kvinna i trettioårsåldern, väderbitet uttryck, grön resmantel, jordfärgade lager, mjuka läderstövlar och slitna handskar. Visuellt ansikte och dräkt skall följa den godkända kvinnliga färdighetsfigurens porträttmaster; denna text är endast ett stöd, inte en ersättande bildreferens.","attributes":{"FYS":14,"INT":15,"KAR":15,"PSY":12,"SMI":17,"STO":12,"STY":13,"ambidextrous":false},"background":"Uppvuxen bland vägfarare och karavanförare. Lärde sig klättra på branta bergspass, läsa väder, spåra försvunna och rädda människor ur ruiner. Hon för bok över märkliga platser men säljer aldrig en karta till någon som vill använda den för att skada oskyldiga.","image_path":null,"motivation":"Kartlägga farliga vägar så att vanliga resenärer överlever dem. Hitta den försvunne vän som en gång räddade hennes liv.","profession":"Jägare","description":"En världsvan äventyrare i sliten grön mantel och praktiska läderarmskydd. Mira är en utforskare med snabba händer, trygg blick och en oförklarlig förmåga att dyka upp där vägarna tar slut.","personality":"Nyfiken, varm och snabbtänkt; skämtar när faran är som störst. Hon minns folks namn, ger barn en chans och ogillar högtidliga titlar.","relationships":"Har en vänskaplig men tävlingsinriktad relation till alvjägaren Caelion. Respekterar Serenyas kunskap, men är misstänksam mot Odrans undanflykter.","equipment_notes":["Resväska med rep, klätterkrokar, handlampa, vattenflaska och nödförband.","Liten läderbunden färddagbok, kartfodral och ovanlig mässingskompass.","Sliten grön mantel; kniv, kortsvärd och reservmynt."],"image_reference":{"note":"Do not substitute a skill scene as portrait; preserve master face.","role":"identity","master":"WIDE_MASTER_PORTRAIT_WOMAN_20261018.png","archetype":"skill_woman"}},{"id":"8648e81b-d6de-4ab7-af8f-0f6e154ad038","name":"Caelion Dimmspår","race":"Skogsalv","tags":["huvudfigur","färdigheter","återkommande","jägare","skogsalv","allierad"],"armor":{"name":"Härdat läder","absorption":4,"armor_type_id":"5d5f3274-101d-412b-b27a-72c0dff469b6"},"hooks":["Rollpersonerna finner ett jaktläger där allt är kvar men ingen jägare syns till.","En bågskytt skjuter ned ett hot utom synhåll och lämnar bara en pil med ett märke.","Caelion ber om eskort genom en mänsklig stad där hans egna färdigheter hjälper föga."],"title":"Alvjägare och skogens väktare","active":true,"gender":"Man","shield":{"bv":null,"fv":null,"name":""},"skills":[{"fv":19,"erf":0,"name":"Pilbågar","skill_id":"pilbagar"},{"fv":19,"erf":0,"name":"Spåra","skill_id":"spara"},{"fv":18,"erf":0,"name":"Smyga","skill_id":"smyga"},{"fv":18,"erf":0,"name":"Kamouflage","skill_id":"kamouflage"},{"fv":18,"erf":0,"name":"Överlevnad","skill_id":"overlevnad"},{"fv":18,"erf":0,"name":"Jaga","skill_id":"jaga"},{"fv":18,"erf":0,"name":"Orientering","skill_id":"orientering"},{"fv":18,"erf":0,"name":"Lyssna","skill_id":"lyssna"},{"fv":18,"erf":0,"name":"Upptäcka fara","skill_id":"upptacka_fara"},{"fv":16,"erf":0,"name":"Zoologi","skill_id":"zoologi"},{"fv":16,"erf":0,"name":"Botanik","skill_id":"botanik"},{"fv":15,"erf":0,"name":"Geografi","skill_id":"geografi"},{"fv":16,"erf":0,"name":"Navigera","skill_id":"navigera"},{"fv":13,"erf":0,"name":"Första hjälpen","skill_id":"forsta_hjalpen"},{"fv":15,"erf":0,"name":"Dolkar","skill_id":"dolkar"},{"fv":16,"erf":0,"name":"Klättra","skill_id":"klattra"},{"fv":17,"erf":0,"name":"Gömma sig","skill_id":"gomma_sig"},{"fv":13,"erf":0,"name":"Simma","skill_id":"simma"},{"fv":14,"erf":0,"name":"Rida","skill_id":"rida"},{"fv":15,"erf":0,"name":"Taktik","skill_id":"taktik"},{"fv":15,"erf":0,"name":"Ilmarsch","skill_id":"ilmarsch"}],"spells":[],"npc_key":"caelion-dimmspar","secrets":"Har sett tecken på att en sedan länge försvunnen släkting fortfarande lever, men har dolt spåren för sitt eget folk.","weapons":[{"bv":null,"fv":19,"bep":2,"name":"Långbåge","tags":["bow","projectile"],"range":"180 m","damage":"1T8+1","length":null,"handling":"2H","weapon_id":"2d574d3d-40f5-4019-bd07-d1bbe083d15d","weaponType":"T","weaponTypeId":"2d574d3d-40f5-4019-bd07-d1bbe083d15d","strengthGroup":3,"weaponCategory":"projectile"},{"bv":9,"fv":15,"bep":0.5,"name":"Dolk","tags":["dagger","edged"],"range":"","damage":"1T4+1","length":0,"handling":"1H","weapon_id":"112c2fed-42ae-41d9-8ca1-f099d2707bbd","weaponType":"L","weaponTypeId":"112c2fed-42ae-41d9-8ca1-f099d2707bbd","strengthGroup":1,"weaponCategory":"melee"}],"gm_notes":"Återkommande expert på spårning, jakt och överlevnad, men inte en problemlösningsmaskin. Använd honom gärna som rivaliserande spårare eller som den som behöver RP:s sociala kunnande. Porträtt: WIDE_MASTER_PORTRAIT_ELF-HUNTER_20261018.png.","weakness":"Har svårt att be om hjälp och dömer ibland människors brådska som dumdristighet. Hans lojalitet till skogen kan stå i konflikt med rollpersonernas mål.","age_years":147,"appearance":"Slank manlig skogsalv med tydlig jägarprägel, ändamålsenliga naturfärgade resekläder, skogsmantel, läderutrustning och långbåge. Ansikte, hud, hår och kläder skall styras av den godkända alvjägarens fotografiska porträttmaster.","attributes":{"FYS":13,"INT":17,"KAR":13,"PSY":16,"SMI":19,"STO":11,"STY":12,"ambidextrous":false},"background":"Har vandrat gränsmarkerna i över ett sekel som spejare, jägare och väktare av gamla skogsstigar. Samlar inga troféer, utan minnen av människor han räddat. Reser numera längre bort från sin hembygd än han vill erkänna.","image_path":null,"motivation":"Skydda de gamla vandringslederna mellan människornas riken och skogens folk. Ta reda på varför djuren överger vissa heliga gläntor.","profession":"Jägare","description":"En tystlåten alvjägare som tycks se fotspår i sten och läsa en hel berättelse ur en bruten kvist. Hans långbåge är lika välvårdad som hans ord är få.","personality":"Eftertänksam, lågmält ironisk, orubbligt lojal sedan han väl vunnit förtroende. Undviker skrävel och svarar ibland på en fråga med en annan fråga.","relationships":"Känner Mira från en räddningsfärd i en lavinrik bergsdal; de räddar varandra men medger sällan vem som började. Har tidigare hjälpt Odran att söka ett bortglömt observatorium.","equipment_notes":["Vårdad långbåge, pilar, jaktkniv och ett diskret koger.","Läder- och tygkläder anpassade för skogen, lätt liggunderlag och fältproviant.","Kniv med inristat minnesmärke från en förlorad färdkamrat."],"image_reference":{"note":"Preserve elf-hunter master face and clothing.","role":"identity","master":"WIDE_MASTER_PORTRAIT_ELF-HUNTER_20261018.png","archetype":"skill_elf_hunter"}},{"id":"e55df1c3-be00-4162-9aac-7485b5d827cb","name":"Serenya Eldslöja","race":"Människa","tags":["huvudfigur","besvärjelser","återkommande","magiker","illusionist"],"armor":{"name":"","absorption":0,"armor_type_id":""},"hooks":["Gruppen blir anlitad för att stjäla tillbaka en bok som stulits från en boktjuv.","Hon uppträder med en illusion på ett värdshus och avslöjar av misstag en annan gästs hemlighet.","Serenya ber om vittnen till ett magiskt experiment som kan få oanade följder."],"title":"Illusionist och eldens väverska","active":true,"gender":"Kvinna","shield":{"bv":null,"fv":null,"name":""},"skills":[{"fv":19,"erf":0,"name":"Kunskap om magi","skill_id":"kunskap_om_magi"},{"fv":16,"erf":0,"name":"Historia","skill_id":"historia"},{"fv":14,"erf":0,"name":"Kulturkännedom","skill_id":"kulturkannedom"},{"fv":16,"erf":0,"name":"Övertala","skill_id":"overtala"},{"fv":16,"erf":0,"name":"Bluffa","skill_id":"bluffa"},{"fv":14,"erf":0,"name":"Heraldik","skill_id":"heraldik"},{"fv":13,"erf":0,"name":"Geografi","skill_id":"geografi"},{"fv":14,"erf":0,"name":"Lyssna","skill_id":"lyssna"},{"fv":14,"erf":0,"name":"Upptäcka fara","skill_id":"upptacka_fara"},{"fv":15,"erf":0,"name":"Finna dolda ting","skill_id":"finna_dolda_ting"},{"fv":12,"erf":0,"name":"Dolkar","skill_id":"dolkar"},{"fv":13,"erf":0,"name":"Stavar","skill_id":"stavar"},{"fv":11,"erf":0,"name":"Låsdyrkning","skill_id":"lasdyrkning"},{"fv":12,"erf":0,"name":"Administrationsjuridik","skill_id":"administrationsjuridik"}],"spells":[{"fv":18,"erf":0,"name":"ILLUSION (F)","rule_id":"c094e4ec-286b-47fa-8d30-7f2350e86535","school_fv":18,"school_id":"illusionism"},{"fv":17,"erf":0,"name":"SINNESMASK","rule_id":"9bc53fb0-c26f-458d-aeb0-b7398b492f40","school_fv":17,"school_id":"illusionism"},{"fv":17,"erf":0,"name":"ELD (F)","rule_id":"d441b542-f8ce-47d8-ac85-5129fee115bc","school_fv":17,"school_id":"illusionism"},{"fv":15,"erf":0,"name":"BLIXT (F, K)","rule_id":"57ec3414-661b-4120-ae17-0a9b57a02c85","school_fv":15,"school_id":"illusionism"},{"fv":16,"erf":0,"name":"FÖRSEGLA (F)","rule_id":"9a2f01bf-d59e-4895-afe8-20e74f8825d0","school_fv":16,"school_id":"illusionism"},{"fv":16,"erf":0,"name":"AVBILD (F)","rule_id":"539e581e-ad0b-44e1-8622-22b65d118eb3","school_fv":16,"school_id":"illusionism"},{"fv":17,"erf":0,"name":"DISTRAKTION (K)","rule_id":"8ecc5bb2-e099-4def-b503-b7e6fc9685d4","school_fv":17,"school_id":"illusionism"},{"fv":13,"erf":0,"name":"FROST (F)","rule_id":"f30feb8f-7a61-40ca-af41-95a0a3fd81ae","school_fv":13,"school_id":"illusionism"},{"fv":14,"erf":0,"name":"ANTIMAGI","rule_id":"1f8a94c6-a1a6-402a-9f55-15b2e8977ade","school_fv":14,"school_id":"allmanna"},{"fv":16,"erf":0,"name":"VARSEBLIVNING","rule_id":"a481c285-31f0-469c-96ce-0599b05305df","school_fv":16,"school_id":"allmanna"},{"fv":15,"erf":0,"name":"BESKYDDARE","rule_id":"e4d78a8a-1d02-49ea-9c88-7a9c68c4a471","school_fv":15,"school_id":"allmanna"},{"fv":14,"erf":0,"name":"LJUSVÄG","rule_id":"813ac317-f0fb-42c1-b808-7d6e2cae9afe","school_fv":14,"school_id":"elementarmagi"},{"fv":13,"erf":0,"name":"JORDVÄG","rule_id":"a60a963d-ccc1-4dc6-8d27-d25eaad7776a","school_fv":13,"school_id":"elementarmagi"}],"npc_key":"serenya-eldsloja","secrets":"Hon känner till en halvfärdig besvärjelse som kan låsa in ett minne i ett föremål; minnet hon själv gömde kan vara farligt om det återfinns.","weapons":[{"bv":7,"fv":13,"bep":2,"name":"Trästav","tags":["staff","wood"],"range":"","damage":"2T4","length":3,"handling":"2H","weapon_id":"bf43afe6-6a84-40dd-acdb-c7a0385ef99c","weaponType":"L","weaponTypeId":"bf43afe6-6a84-40dd-acdb-c7a0385ef99c","strengthGroup":1,"weaponCategory":"melee"},{"bv":9,"fv":12,"bep":0.5,"name":"Dolk","tags":["dagger","edged"],"range":"","damage":"1T4+1","length":0,"handling":"1H","weapon_id":"112c2fed-42ae-41d9-8ca1-f099d2707bbd","weaponType":"L","weaponTypeId":"112c2fed-42ae-41d9-8ca1-f099d2707bbd","strengthGroup":1,"weaponCategory":"melee"}],"gm_notes":"Återkommande besvärjare. Använd kunnandet till pussel, sociala komplikationer och magisk hjälp snarare än att låta henne lösa hela äventyret. Expert-FV och skolkopplingar bygger på registrerade besvärjelser. Ingen bild är ännu direkt kopplad till detta SLP-original.","weakness":"Kan inte motstå en intellektuell utmaning. Blir personlig när någon förlöjligar hennes magi eller hennes läromästare.","age_years":37,"appearance":"Den etablerade kvinnliga besvärjelsemagikerns fotorealistiska identitet, praktisk men säregen magisk klädsel, igenkännbar hållning och tydliga magiska ljuseffekter. Framtida porträtt måste härledas från godkända besvärjelseillustrationer, inte hittas på på nytt.","attributes":{"FYS":12,"INT":19,"KAR":16,"PSY":19,"SMI":14,"STO":11,"STY":9,"ambidextrous":false},"background":"Fick sin tidigaste undervisning av Odran men lämnade honom efter en häftig tvist om hur man använder förseglade texter. Vandrar nu mellan bibliotek, ruiner och marknadsstäder med en samling välbevarade rullar.","image_path":null,"motivation":"Bevisa att magi kan bevara kunskap utan att lägga världen under sig. Återställa ett splittrat arkiv som hennes gamla lärare vägrar tala om.","profession":"Trollkarl","description":"En skarpsinnig kvinnlig magiker vars vackra illusioner ibland avslöjar en obekvämare verklighet. Hon föredrar att vinna en konflikt utan blodspillan, men hennes vrede kan lysa upp en hel ruin.","personality":"Karismatisk, analytisk och lekfull, med ett märkbart drag av stolthet. Ställer ofta en prövande fråga när någon begär hjälp.","relationships":"Tidigare elev till Odran Stjärnfall, med både djup tillgivenhet och olösta konflikter. Uppskattar Miras mod och smågrälar gärna med Caelion om vad som räknas som verklighet.","equipment_notes":["Besvärjelsebok med lösa blad, förseglingsvax och glasampuller.","Reskappa, metallspegel, runkrita och ett kort svärd hon sällan använder.","En enkel stav som fokus, inget automatiskt magiskt vapen."],"image_reference":{"note":"Identify and approve specific canonical portrait before assigning image_path.","role":"visual_identity","master":"etablerad kvinnlig besvärjelseillustrationsfigur","archetype":"spell_woman"}},{"id":"7213a023-3cbc-4239-813f-c05e3bec8f8b","name":"Odran Stjärnfall","race":"Människa","tags":["huvudfigur","besvärjelser","återkommande","magiker","mentor"],"armor":{"name":"","absorption":0,"armor_type_id":""},"hooks":["Ett värdshus får ett besök av en äldre magiker som påstår sig känna igen en rollpersons dröm.","Han ber gruppen leverera ett brev till en person som officiellt inte finns.","När en försegling bryts visar sig Odran redan ha varit där för många år sedan."],"title":"Vandrande lärd magiker och väderläsare","active":true,"gender":"Man","shield":{"bv":null,"fv":null,"name":""},"skills":[{"fv":19,"erf":0,"name":"Kunskap om magi","skill_id":"kunskap_om_magi"},{"fv":18,"erf":0,"name":"Historia","skill_id":"historia"},{"fv":18,"erf":0,"name":"Astrologi","skill_id":"astrologi"},{"fv":16,"erf":0,"name":"Geografi","skill_id":"geografi"},{"fv":14,"erf":0,"name":"Zoologi","skill_id":"zoologi"},{"fv":13,"erf":0,"name":"Botanik","skill_id":"botanik"},{"fv":15,"erf":0,"name":"Övertala","skill_id":"overtala"},{"fv":18,"erf":0,"name":"Kulturkännedom","skill_id":"kulturkannedom"},{"fv":16,"erf":0,"name":"Lyssna","skill_id":"lyssna"},{"fv":15,"erf":0,"name":"Upptäcka fara","skill_id":"upptacka_fara"},{"fv":14,"erf":0,"name":"Första hjälpen","skill_id":"forsta_hjalpen"},{"fv":13,"erf":0,"name":"Läkekonst","skill_id":"lakekonst"},{"fv":13,"erf":0,"name":"Stavar","skill_id":"stavar"},{"fv":10,"erf":0,"name":"Dolkar","skill_id":"dolkar"},{"fv":14,"erf":0,"name":"Navigera","skill_id":"navigera"},{"fv":15,"erf":0,"name":"Geologi","skill_id":"geologi"},{"fv":16,"erf":0,"name":"Heraldik","skill_id":"heraldik"},{"fv":16,"erf":0,"name":"Räkning","skill_id":"rakning"}],"spells":[{"fv":18,"erf":0,"name":"MAGISK SYN","rule_id":"3a4860c2-f389-44a9-9d34-144994f84774","school_fv":18,"school_id":"mentalism"},{"fv":17,"erf":0,"name":"SANNSYN","rule_id":"e4aa1ce6-6ec6-4269-963a-e4e6b724276a","school_fv":17,"school_id":"mentalism"},{"fv":16,"erf":0,"name":"OSYNLIGHET","rule_id":"e72abdf8-c016-4b1e-9674-eee97923bc40","school_fv":16,"school_id":"mentalism"},{"fv":15,"erf":0,"name":"FLYGA","rule_id":"e11e3b67-23dc-4f66-80c2-0c129af67de0","school_fv":15,"school_id":"mentalism"},{"fv":18,"erf":0,"name":"MINNE","rule_id":"ed6e452e-16bb-4b2d-b0e8-9b24187b2a5b","school_fv":18,"school_id":"mentalism"},{"fv":15,"erf":0,"name":"ORÄDD","rule_id":"c648413f-2ed6-4d00-8a21-039db74ee429","school_fv":15,"school_id":"mentalism"},{"fv":15,"erf":0,"name":"ORIENTERING","rule_id":"9e9b12f7-9cac-43ed-82cf-15953a5e7053","school_fv":15,"school_id":"mentalism"},{"fv":16,"erf":0,"name":"DIMMA","rule_id":"1b5c4c32-bc4b-404e-a253-da804f2faef7","school_fv":16,"school_id":"animism"},{"fv":16,"erf":0,"name":"HELA","rule_id":"618d3e0b-6de0-4657-9664-e5a4f5ae1418","school_fv":16,"school_id":"animism"},{"fv":15,"erf":0,"name":"RENA","rule_id":"912c993c-d31f-4c9e-a573-a28ab4536c50","school_fv":15,"school_id":"animism"},{"fv":16,"erf":0,"name":"TALA MED VARELSE","rule_id":"a8ab5aca-9298-4f68-8561-3cd5cd38cd1c","school_fv":16,"school_id":"animism"},{"fv":16,"erf":0,"name":"VÄDERFÖRUTSÄGELSE","rule_id":"4e059a95-ebe6-4178-a772-063aaf8c01f5","school_fv":16,"school_id":"animism"},{"fv":14,"erf":0,"name":"VINDKONTROLL","rule_id":"9f632181-222d-4c78-b099-f716ced6af98","school_fv":14,"school_id":"animism"},{"fv":17,"erf":0,"name":"ANTIMAGI","rule_id":"1f8a94c6-a1a6-402a-9f55-15b2e8977ade","school_fv":17,"school_id":"allmanna"},{"fv":17,"erf":0,"name":"BESKYDDARE","rule_id":"e4d78a8a-1d02-49ea-9c88-7a9c68c4a471","school_fv":17,"school_id":"allmanna"},{"fv":18,"erf":0,"name":"VARSEBLIVNING","rule_id":"a481c285-31f0-469c-96ce-0599b05305df","school_fv":18,"school_id":"allmanna"}],"npc_key":"odran-stjarnfall","secrets":"En förrädisk varning han en gång tystade återkommer nu på olika platser i form av samma tre ord. Han anar vem som skickar den men vågar ännu inte säga namnet.","weapons":[{"bv":7,"fv":13,"bep":2,"name":"Trästav","tags":["staff","wood"],"range":"","damage":"2T4","length":3,"handling":"2H","weapon_id":"bf43afe6-6a84-40dd-acdb-c7a0385ef99c","weaponType":"L","weaponTypeId":"bf43afe6-6a84-40dd-acdb-c7a0385ef99c","strengthGroup":1,"weaponCategory":"melee"},{"bv":9,"fv":10,"bep":0.5,"name":"Dolk","tags":["dagger","edged"],"range":"","damage":"1T4+1","length":0,"handling":"1H","weapon_id":"112c2fed-42ae-41d9-8ca1-f099d2707bbd","weaponType":"L","weaponTypeId":"112c2fed-42ae-41d9-8ca1-f099d2707bbd","strengthGroup":1,"weaponCategory":"melee"}],"gm_notes":"Återkommande lärd resenär, inspiratör, potentiell uppdragsgivare och tveksam mentor. Använd inte ''allvetande magiker'' för att ge facit. Besvärjelserna begränsas till Expert-registrets befintliga poster. Ingen kanonisk SLP-porträttfil kopplad än.","weakness":"Hemlighetsfull ända till självdestruktivitet. Har svårt att erkänna när hans tidigare beslut skadat andra.","age_years":64,"appearance":"Den etablerade manliga besvärjelsemagikerns fotografiska identitet med hans kända klädsel och gestik. Undvik ny, opålitlig ansiktsbeskrivning tills exakt porträttreferens är länkad.","attributes":{"FYS":11,"INT":19,"KAR":15,"PSY":20,"SMI":12,"STO":12,"STY":8,"ambidextrous":false},"background":"Växte upp vid en liten lärdomsskola och blev efter årtionden av resor en mästare på mentala skeenden, vädertecken och magisk diagnostik. Ingen vet hur många gånger han lämnat ett värdshus precis före en katastrof.","image_path":null,"motivation":"Förhindra att en gammal lära används för att utplåna människors fria vilja. Laga broarna till sin tidigare elev Serenya.","profession":"Trollkarl","description":"En vänligt leende men svårtolkad manlig trollkarl, mer intresserad av ett barns märkliga dröm än av en hertigs guldkista. Hans kunskap verkar till synes gränslös, men hans egna misstag jagar honom.","personality":"Tålmodig, underfundig och ofta självironisk. Talar i liknelser, njuter av starkt te och låter gärna andra få äran.","relationships":"Serenya är hans tidigare elev; deras osämja bottnar i en gammal försegling. Caelion har följt honom till en övergiven stjärnplats; Mira litar på honom bara när han talar klart och tydligt.","equipment_notes":["Liten samling pergament, stjärnkarta, mässingsinstrument och teburk.","Sliten resstav och en dold dolk av vanligt stål.","Ett anonymt brev med tre ord som han vägrar öppna."],"image_reference":{"note":"Identify and approve specific canonical portrait before assigning image_path.","role":"visual_identity","master":"etablerad manlig besvärjelseillustrationsfigur","archetype":"spell_man"}}]'::jsonb))
insert into public.global_npcs (
  id,npc_key,name,title,description,gm_notes,age_years,race,gender,profession,
  appearance,personality,motivation,weakness,background,relationships,secrets,hooks,
  equipment_notes,image_reference,image_path,attributes,skills,weapons,spells,shield,armor,tags,active
)
select
 (j->>'id')::uuid,j->>'npc_key',j->>'name',j->>'title',j->>'description',
 j->>'gm_notes',(j->>'age_years')::integer,j->>'race',j->>'gender',j->>'profession',
 j->>'appearance',j->>'personality',j->>'motivation',j->>'weakness',j->>'background',
 j->>'relationships',j->>'secrets',j->'hooks',j->'equipment_notes',
 j->'image_reference',j->>'image_path',j->'attributes',
 (select coalesce(jsonb_agg(z.item || jsonb_build_object('skill_id',s.id,'name',s.name)),'[]'::jsonb)
   from jsonb_array_elements(j->'skills') as z(item)
   join public.rule_skills s on s.id=z.item->>'skill_id'),
 (select coalesce(jsonb_agg(z.item || jsonb_build_object('weapon_id',w.id,'weaponTypeId',w.id)),'[]'::jsonb)
   from jsonb_array_elements(j->'weapons') as z(item)
   join public.rule_weapons w on w.name=z.item->>'name'),
 (select coalesce(jsonb_agg(z.item || jsonb_build_object('rule_id',sp.id,'school_id',sp.school_id)),'[]'::jsonb)
   from jsonb_array_elements(j->'spells') as z(item)
   join public.rule_spells sp on sp.name=z.item->>'name' and sp.canonical_expert=true),
 j->'shield',
 jsonb_set(j->'armor','{armor_type_id}',to_jsonb(
   coalesce((select id::text from public.rule_armor_types t where t.name=j->'armor'->>'name' limit 1),'')
 ),true),
 array(select jsonb_array_elements_text(j->'tags')),(j->>'active')::boolean
from source
on conflict(npc_key) do nothing;
